// Clamp the aim angle to ±80° and map it linearly onto one of 8 columns
function angleToCol(angle) {
  const clamped = Math.max(-80, Math.min(80, angle));
  const t = (clamped + 80) / 160;
  return Math.min(COLS - 1, Math.floor(t * COLS));
}
// Attach below the lowest bubble in that column; an empty column hits the ceiling,
// a full column returns null (game over)
function findAttachCell(grid, col) {
  for (let r = ROWS - 1; r >= 0; r--) {
    if (grid[r][col]) {
      if (r + 1 >= ROWS) return null;
      return { row: r + 1, col };
    }
  }
  return { row: 0, col };
}

function findFloating(grid) {
  const anchored = new Set();
  const queue = [];
  for (let c = 0; c < COLS; c++) {          // top-row bubbles are anchored by default
    if (grid[0][c]) {
      anchored.add(`0,${c}`);
      queue.push([0, c]);
    }
  }
  while (queue.length > 0) {                // 8-way BFS marks every anchored bubble
    const [r, c] = queue.shift();
    for (const [nr, nc] of neighbors(r, c)) {
      if (nr < 0 || nr >= ROWS || nc < 0 || nc >= COLS) continue;
      const key = `${nr},${nc}`;
      if (anchored.has(key)) continue;
      if (grid[nr][nc]) {
        anchored.add(key);
        queue.push([nr, nc]);
      }
    }
  }
  // anything not anchored is floating: it drops and pays 20 points each
}
